html:
{% set id=frappe.get_all("ID", filters={"parent": doc.employee_number, "parenttype": "Employee", "id_is_primary": "1"}, fields=["id_number","id_other_type","id_selected_type"]) | list %}
{% set id_number = id[0].id_number %}

{% if id[0].id_selected_type == "OTHERS" %}
    {{id[0].id_other_type}}
    {{id_number}}
{% else %}
    {{id[0].id_selected_type}}
    {{id_number}}
{% endif %}

{% set mother=frappe.get_all("Family Background", filters={"parent": doc.employee_number, "parenttype": "Employee", "relationship": "Mother"}, fields=["first_name","surname","middle_name","name_extension"]) | list %}
{% if (mother is defined) and mother %}
    {% set mother_first_name = mother[0].first_name %}
    {{mother_first_name}}
{% endif %}
